import { BedrockRuntimeClient, ConverseCommand } from "@aws-sdk/client-bedrock-runtime";
import { Message, TextContent, ToolRequest, ToolResponse } from "../types.js";
import { ToolManager } from "./ToolManager.js";
import { Logger, LogLevel, createDefaultLogger } from "../utils/logging.js";
import { MessageStorage, InMemoryMessageStorage, SessionIdentifier } from "../storage/index.js";

/**
 * Agent for interacting with AWS Bedrock's Converse API
 */
export class ConverseAgent {
    private modelId: string;
    private region: string;
    private bedrockClient: BedrockRuntimeClient;
    private systemPrompt: string;
    private messageStorage: MessageStorage;
    private session: SessionIdentifier;
    private toolManager: ToolManager | null;
    private responseOutputTags: [string, string] | [];
    private maxTokens: number;
    private temperature: number;
    private logger: Logger;

    /**
     * Create a new ConverseAgent
     *
     * @param modelId - The AWS Bedrock model ID to use
     * @param options - Configuration options
     */
    constructor(
        modelId: string,
        options: {
            region?: string;
            systemPrompt?: string;
            toolManager?: ToolManager;
            responseOutputTags?: [string, string];
            maxTokens?: number;
            temperature?: number;
            messageStorage?: MessageStorage;
            session?: SessionIdentifier;
        } = {}
    ) {
        this.modelId = modelId;
        this.region = options.region || 'us-east-1';
        this.bedrockClient = new BedrockRuntimeClient({ region: this.region });
        this.systemPrompt = options.systemPrompt || `You are a helpful assistant with access to external tools.
                                                    - Use available tools **only when necessary** to provide accurate or up-to-date information.
                                                    - If a question can be answered based on your knowledge, respond directly **without using tools**.
                                                    - If a tool is required:
                                                        1. **Check if all necessary parameters are available.** If they are, use the tool directly.
                                                        2. **If any parameters are missing, do not proceed.** Instead, ask the user for the required information, explaining why it is needed.
                                                        3. **Wait for the user's response before using the tool.**
                                                    - If the user asks multiple questions, **handle them one by one**.
                                                    - If some questions require tools and others don't, **answer what you can immediately**, then use tools as needed.
                                                    - After using a tool, continue answering any remaining questions.
                                                    `;

        // Initialize storage and session
        this.messageStorage = options.messageStorage || new InMemoryMessageStorage();
        this.session = options.session || { sessionId: this.generateSessionId() };

        this.toolManager = options.toolManager || null;
        this.responseOutputTags = options.responseOutputTags || [];
        this.maxTokens = options.maxTokens || 2000;
        this.temperature = options.temperature || 0.7;
        this.logger = createDefaultLogger('ConverseAgent');
        this.logger.setLevel(LogLevel.INFO); // Set to DEBUG to see all logs
    }

    /**
     * Generate a unique session ID
     */
    private generateSessionId(): string {
        return `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    }

    /**
     * Invoke the agent with a text prompt
     * 
     * @param prompt - The text prompt to send
     * @returns A promise that resolves to the agent's response
     */
    async invokeWithPrompt(prompt: string): Promise<string> {
        const content: TextContent[] = [{ text: prompt }];
        return await this.invoke(content);
    }

    /**
     * Invoke the agent with content
     *
     * @param content - The content to send
     * @returns A promise that resolves to the agent's response
     */
    async invoke(content: any[]): Promise<string> {
        // Check if the content is a tool result
        const isToolResult = content.length > 0 && content[0].toolResult !== undefined;

        if (!isToolResult) {
            // This is a new user query, clear accumulated tool results
            this.clearAccumulatedToolResults();
        }

        if (isToolResult) {
            this.logger.debug("Detected tool result in invoke:", JSON.stringify(content, null, 2));

            // For tool results, we need to add them to the last assistant message
            // First, check if we have an assistant message
            const messages = await this.messageStorage.getMessages(this.session);
            let assistantMessageIndex = -1;
            for (let i = messages.length - 1; i >= 0; i--) {
                if (messages[i].role === "assistant") {
                    assistantMessageIndex = i;
                    break;
                }
            }

            if (assistantMessageIndex >= 0) {
                // Replace the assistant message with a new one containing the tool results
                const updatedMessage: Message = {
                    role: "assistant",
                    content: content
                };
                await this.messageStorage.updateMessage(this.session, assistantMessageIndex, updatedMessage);
                this.logger.debug("Updated assistant message with tool results");
            } else {
                // If no assistant message found, add a new one
                const newMessage: Message = {
                    role: "assistant",
                    content: content
                };
                await this.messageStorage.addMessage(this.session, newMessage);
                this.logger.debug("Added new assistant message with tool results");
            }
        } else {
            // Regular user message
            const userMessage: Message = {
                role: "user",
                content: content,
            };
            await this.messageStorage.addMessage(this.session, userMessage);
            this.logger.debug("Added user message");
        }

        const messages = await this.messageStorage.getMessages(this.session);
        this.logger.debug("Sending message to model:", JSON.stringify(messages[messages.length - 1], null, 2));
        const response = await this._getConverseResponse();
        return await this._handleResponse(response);
    }

    /**
     * Get the conversation history
     *
     * @returns The conversation history
     */
    async getConversationHistory(): Promise<Message[]> {
        return await this.messageStorage.getMessages(this.session);
    }

    /**
     * Clear the conversation history
     */
    async clearConversationHistory(): Promise<void> {
        await this.messageStorage.clearMessages(this.session);
    }

    /**
     * Set the tool manager
     * 
     * @param toolManager - The tool manager to use
     */
    setToolManager(toolManager: ToolManager): void {
        this.toolManager = toolManager;
    }

    /**
     * Get the Bedrock client
     * 
     * @returns The Bedrock client
     */
    getBedrockClient(): BedrockRuntimeClient {
        return this.bedrockClient;
    }

    /**
     * Get a response from the Converse API
     *
     * @returns A promise that resolves to the Converse API response
     * @private
     */
    private async _getConverseResponse() {
        // Get current messages from storage
        const messages = await this.messageStorage.getMessages(this.session);

        // Build the command input with system prompt, inference config, and (optionally) tool config
        const commandInput: any = {
            modelId: this.modelId,
            messages: messages,
            system: [{ text: this.systemPrompt }],
            inferenceConfig: {
                maxTokens: this.maxTokens,
                temperature: this.temperature,
            },
        };

        if (this.toolManager) {
            const toolConfig = this.toolManager.getToolConfig();
            if (toolConfig) {
                commandInput.toolConfig = toolConfig;
            }
        }

        // Log the full conversation history for debugging
        this.logger.debug("Full conversation history:", JSON.stringify(messages, null, 2));

        // Log the complete API payload for debugging
        this.logger.debug("CONVERSE API PAYLOAD:", JSON.stringify(commandInput, null, 2));

        // Log the exact structure of each message for debugging
        this.logger.debug("Message structure breakdown:");
        messages.forEach((msg: Message, index: number) => {
            this.logger.debug(`Message ${index} (${msg.role}):`);
            if (Array.isArray(msg.content)) {
                msg.content.forEach((contentItem: any, contentIndex: number) => {
                    this.logger.debug(`  Content item ${contentIndex} type: ${Object.keys(contentItem).join(', ')}`);
                });
            } else {
                this.logger.debug(`  Content is not an array: ${typeof msg.content}`);
            }
        });

        const command = new ConverseCommand(commandInput);
        return await this.bedrockClient.send(command);
    }

    /**
     * Handle the response from the Converse API
     * 
     * @param response - The response from the Converse API
     * @returns A promise that resolves to the agent's response
     * @private
     */
    // Store accumulated tool results across API calls
    private accumulatedToolResults: { name: string, text: string }[] = [];

    private async _handleResponse(response: any): Promise<string> {
        this.logger.debug("Received response from Bedrock:", JSON.stringify(response, null, 2));

        // Check for valid response
        if (!response.output || !response.output.message) {
            this.logger.error("Invalid response structure, missing output.message");
            this.logger.error("Response:", response);
            throw new Error("Invalid response structure from Bedrock API");
        }

        // Log the message content for debugging
        this.logger.debug("Message content before pushing to history:",
            JSON.stringify(response.output.message.content, null, 2));

        const stopReason = response.stopReason;
        this.logger.debug("Stop reason:", stopReason);

        if (stopReason === 'end_turn' || stopReason === 'stop_sequence') {
            // Add the response message to the conversation history
            await this.messageStorage.addMessage(this.session, response.output.message);

            try {
                const message = response.output.message;
                const content = message.content;

                if (!content || content.length === 0) {
                    this.logger.error("No content in message");
                    return '';
                }

                this.logger.debug("Content:", JSON.stringify(content, null, 2));
                let text = (content[0] && content[0].text) || '';
                this.logger.debug("Extracted text:", text ? text.substring(0, 100) + "..." : "(empty)");

                if (this.responseOutputTags.length === 2) {
                    const [startTag, endTag] = this.responseOutputTags;
                    // The 's' flag allows dot to match newlines
                    const pattern = new RegExp(`${startTag}(.*?)${endTag}`, 's');
                    const match = text.match(pattern);
                    if (match) {
                        text = match[1];
                    }
                }

                return text;
            } catch (err) {
                this.logger.error("Error extracting text from response:", err);
                return '';
            }
        } else if (stopReason === 'tool_use') {
            if (!this.toolManager) {
                throw new Error("Tool use requested but no tool manager is set");
            }

            try {
                // First, add the assistant message with toolUse to the conversation history
                await this.messageStorage.addMessage(this.session, response.output.message);

                // Process each tool use and collect results
                const toolResults = [];
                let combinedText = "";

                this.logger.debug("Processing tool use blocks...");
                for (const contentItem of response.output.message.content) {
                    if (contentItem.toolUse) {
                        const toolRequest: ToolRequest = {
                            toolUseId: contentItem.toolUse.toolUseId,
                            name: contentItem.toolUse.name,
                            input: contentItem.toolUse.input || {},
                        };

                        this.logger.info(`Gathering data using tool: ${toolRequest.name} ...`);
                        this.logger.debug(`Tool request: ${JSON.stringify(toolRequest, null, 2)}`);

                        const toolResult = await this.toolManager.executeTool(toolRequest);
                        this.logger.info("Analyzing data ...");
                        this.logger.debug(`Tool result: ${JSON.stringify(toolResult, null, 2)}`);

                        // Add the tool result to the collection
                        toolResults.push({
                            toolResult: {
                                toolUseId: toolRequest.toolUseId,
                                content: toolResult.content || [],
                                status: toolResult.status || 'success'
                            }
                        });

                        // Extract text from tool result for the combined response
                        if (toolResult && toolResult.content) {
                            for (const item of toolResult.content) {
                                if (item.text) {
                                    combinedText += item.text + " ";
                                }
                            }
                        }
                    }
                }

                // Add a user message with the tool results
                if (toolResults.length > 0) {
                    const userMessageWithToolResults: Message = {
                        role: "user",
                        content: toolResults
                    };
                    await this.messageStorage.addMessage(this.session, userMessageWithToolResults);

                    // Now get the next response from the model
                    const nextResponse = await this._getConverseResponse();
                    return await this._handleResponse(nextResponse);
                }

                return combinedText.trim();
            } catch (e) {
                this.logger.error("Error executing tool:", e);
                throw new Error(`Missing required tool use field: ${e instanceof Error ? e.message : String(e)}`);
            }
        } else if (stopReason === 'max_tokens') {
            // Add the response message to the conversation history
            await this.messageStorage.addMessage(this.session, response.output.message);

            // Continue the conversation if the token limit is reached
            return await this.invokeWithPrompt('Please continue.');
        } else {
            throw new Error(`Unknown stop reason: ${stopReason}`);
        }
    }

    /**
     * Clear accumulated tool results
     */
    clearAccumulatedToolResults(): void {
        this.accumulatedToolResults = [];
    }

    /**
     * Format the combined response to make it more natural
     * 
     * @param initialText - The initial text from the model
     * @param toolResultText - The text from the tool result
     * @param toolName - The name of the tool (not used in generic implementation)
     * @returns A formatted combined response
     * @private
     */
    private formatCombinedResponse(initialText: string, toolResultText: string, toolName: string): string {
        // Generic formatting for all tools
        return `${initialText}\n\n${toolResultText}`;
    }
}

import { EventEmitter } from "events";
import { MCPClient } from "mcp-client";
import { ConverseAgent } from "../core/ConverseAgent.js";
import { ToolManager } from "../core/ToolManager.js";
import { LogLevel } from "../utils/logging.js";
import { BedrockMCPClientConfig, BedrockMCPClientEmitter, ToolHandler } from "../types.js";
import {
    MessageStorage,
    InMemoryMessageStorage,
    RedisMessageStorage,
    SessionIdentifier
} from "../storage/index.js";

/**
 * Client for interacting with AWS Bedrock and MCP servers
 */
export class BedrockMCPClient {
    private agent: ConverseAgent;
    private toolManager: ToolManager;
    private messageStorage: MessageStorage;
    private mcpClient: MCPClient | null = null;
    private mcpServerUrl: string | null = null;
    private clientName: string;
    private clientVersion: string;
    private emitter: BedrockMCPClientEmitter;
    private isConnected: boolean = false;

    /**
     * Create a new BedrockMCPClient
     *
     * @param config - Configuration options
     */
    constructor(config: BedrockMCPClientConfig) {
        // Initialize the tool manager
        this.toolManager = new ToolManager();

        // Initialize storage based on configuration
        this.messageStorage = this.createStorage(config);

        // Create session identifier
        const session: SessionIdentifier = {
            sessionId: config.sessionId || this.generateSessionId(),
            userId: config.userId
        };

        // Initialize the agent
        this.agent = new ConverseAgent(config.modelId, {
            region: config.region,
            systemPrompt: config.systemPrompt,
            toolManager: this.toolManager,
            responseOutputTags: config.responseOutputTags,
            maxTokens: config.maxTokens,
            temperature: config.temperature,
            messageStorage: this.messageStorage,
            session: session
        });

        // Store MCP configuration
        this.mcpServerUrl = config.mcpServerUrl || null;
        this.clientName = config.clientName || "BedrockMCPClient";
        this.clientVersion = config.clientVersion || "1.0.0";

        // Initialize event emitter
        this.emitter = new EventEmitter() as BedrockMCPClientEmitter;

        // Initialize storage
        this.initializeStorage();
    }

    /**
     * Create storage instance based on configuration
     */
    private createStorage(config: BedrockMCPClientConfig): MessageStorage {
        if (!config.storage || config.storage.type === 'memory') {
            return new InMemoryMessageStorage();
        } else if (config.storage.type === 'redis') {
            return new RedisMessageStorage(config.storage.config);
        } else {
            throw new Error(`Unsupported storage type: ${(config.storage as any).type}`);
        }
    }

    /**
     * Initialize storage connection
     */
    private async initializeStorage(): Promise<void> {
        try {
            await this.messageStorage.initialize();
        } catch (error) {
            this.emitter.emit("error", new Error(`Failed to initialize storage: ${error instanceof Error ? error.message : String(error)}`));
        }
    }

    /**
     * Generate a unique session ID
     */
    private generateSessionId(): string {
        return `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    }

    /**
     * Connect to the MCP server
     * 
     * @returns A promise that resolves when the connection is established
     * @throws Error if the MCP server URL is not provided
     */
    async connect(): Promise<void> {
        if (!this.mcpServerUrl) {
            throw new Error("MCP server URL is required to connect");
        }

        try {
            this.emitter.emit("message", "Connecting to MCP server...");

            // Initialize MCP client
            this.mcpClient = new MCPClient({
                name: this.clientName,
                version: this.clientVersion,
            });

            // Connect to the MCP server
            await this.mcpClient.connect({
                type: "sse",
                url: this.mcpServerUrl
            });

            this.emitter.emit("message", "Connected to MCP server");
            this.emitter.emit("connected");
            this.isConnected = true;

            // Register MCP tools
            await this.registerMCPTools();
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            this.emitter.emit("error", new Error(`Error connecting to MCP server: ${errorMessage}`));
            throw error;
        }
    }

    /**
     * Disconnect from the MCP server and close storage
     *
     * @returns A promise that resolves when the connection is closed
     */
    async disconnect(): Promise<void> {
        if (this.mcpClient) {
            try {
                // MCPClient doesn't have a disconnect method, so we just mark as disconnected
                this.mcpClient = null;
                this.emitter.emit("message", "Disconnected from MCP server");
                this.emitter.emit("disconnected");
                this.isConnected = false;
            } catch (error) {
                const errorMessage = error instanceof Error ? error.message : String(error);
                this.emitter.emit("error", new Error(`Error disconnecting from MCP server: ${errorMessage}`));
                throw error;
            }
        }

        // Close storage connection
        try {
            await this.messageStorage.close();
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            this.emitter.emit("error", new Error(`Error closing storage: ${errorMessage}`));
        }
    }

    /**
     * Check if the client is connected to the MCP server
     * 
     * @returns True if connected, false otherwise
     */
    isConnectedToMCP(): boolean {
        return this.isConnected;
    }

    /**
     * Send a prompt to the agent
     * 
     * @param prompt - The prompt to send
     * @returns A promise that resolves to the agent's response
     */
    async sendPrompt(prompt: string): Promise<string> {
        try {
            this.emitter.emit("response:start");
            this.emitter.emit("message", `Sending prompt to ${this.agent.constructor.name}...`);

            const response = await this.agent.invokeWithPrompt(prompt);

            this.emitter.emit("response:chunk", response);
            this.emitter.emit("response:end", response);

            return response;
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            this.emitter.emit("error", new Error(`Error sending prompt: ${errorMessage}`));
            throw error;
        }
    }

    /**
     * Register a custom tool
     * 
     * @param name - The name of the tool
     * @param handler - The function to execute when the tool is called
     * @param description - Optional description of the tool
     * @param inputSchema - Optional JSON schema for the tool's input
     */
    registerTool(
        name: string,
        handler: ToolHandler,
        description?: string,
        inputSchema?: Record<string, any>
    ): void {
        const wrappedHandler: ToolHandler = async (name, input) => {
            try {
                this.emitter.emit("tool:start", name, input);
                const result = await handler(name, input);
                this.emitter.emit("tool:end", name, result);
                return result;
            } catch (error) {
                const errorMessage = error instanceof Error ? error.message : String(error);
                this.emitter.emit("error", new Error(`Error executing tool ${name}: ${errorMessage}`));
                throw error;
            }
        };

        this.toolManager.registerTool(name, wrappedHandler, description, inputSchema);
    }

    /**
     * Get all registered tools
     * 
     * @returns An array of tool names and descriptions
     */
    getTools(): Array<{ name: string; description?: string }> {
        return this.toolManager.getTools();
    }

    /**
     * Get the event emitter
     * 
     * @returns The event emitter
     */
    getEmitter(): BedrockMCPClientEmitter {
        return this.emitter;
    }

    /**
     * Get the agent
     * 
     * @returns The agent
     */
    getAgent(): ConverseAgent {
        return this.agent;
    }

    /**
     * Get the conversation history
     *
     * @returns The conversation history
     */
    async getConversationHistory() {
        return await this.agent.getConversationHistory();
    }

    /**
     * Clear the conversation history
     */
    async clearConversationHistory(): Promise<void> {
        await this.agent.clearConversationHistory();
    }

    /**
     * Set the log level for the client and its components
     *
     * @param level - The log level to set
     */
    setLogLevel(level: LogLevel): void {
        // Access the logger property of the agent and toolManager
        // These properties are private, but we know they exist from our implementation
        (this.agent as any).logger?.setLevel(level);
        (this.toolManager as any).logger?.setLevel(level);

        // Set log level for storage if it supports it
        if (this.messageStorage && typeof (this.messageStorage as any).setLogLevel === 'function') {
            (this.messageStorage as any).setLogLevel(level);
        }
    }

    /**
     * Get storage health status
     *
     * @returns True if storage is healthy
     */
    async isStorageHealthy(): Promise<boolean> {
        try {
            return await this.messageStorage.isHealthy();
        } catch (error) {
            return false;
        }
    }

    /**
     * Get storage type information
     *
     * @returns Storage type and additional info
     */
    getStorageInfo(): { type: string; isHealthy?: boolean } {
        if (this.messageStorage instanceof InMemoryMessageStorage) {
            return { type: 'memory' };
        } else if (this.messageStorage instanceof RedisMessageStorage) {
            return { type: 'redis' };
        } else {
            return { type: 'unknown' };
        }
    }

    /**
     * Register tools from the MCP server
     * 
     * @private
     */
    private async registerMCPTools(): Promise<void> {
        if (!this.mcpClient) {
            return;
        }

        try {
            // Get tools from MCP client
            const tools = await this.mcpClient.getAllTools();

            if (tools.length === 0) {
                this.emitter.emit("message", "No tools available from MCP server");
                return;
            }

            // Register each tool
            for (const tool of tools) {
                if (!tool.name) {
                    this.emitter.emit("message", `Skipping tool with missing name: ${JSON.stringify(tool)}`);
                    continue;
                }

                try {
                    const toolFunction: ToolHandler = async (name, input) => {
                        try {
                            // Make sure input is an object with the expected structure
                            const formattedInput = input || {};
                            const callToolParams = {
                                name: name,
                                arguments: formattedInput
                            };

                            return await this.mcpClient!.callTool(callToolParams);
                        } catch (error) {
                            const errorMessage = error instanceof Error ? error.message : String(error);
                            this.emitter.emit("error", new Error(`Error calling MCP tool ${name}: ${errorMessage}`));
                            throw error;
                        }
                    };

                    this.registerTool(
                        tool.name,
                        toolFunction,
                        tool.description || "",
                        tool.inputSchema || { type: "object", properties: {}, required: [] }
                    );

                    this.emitter.emit("message", `Registered MCP tool: ${tool.name}`);
                } catch (error) {
                    const errorMessage = error instanceof Error ? error.message : String(error);
                    this.emitter.emit("error", new Error(`Error registering tool ${tool.name}: ${errorMessage}`));
                }
            }

            this.emitter.emit("message", `Registered ${tools.length} MCP tools`);
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            this.emitter.emit("error", new Error(`Error getting tools from MCP client: ${errorMessage}`));
        }
    }
}

# Bedrock MCP Connector

A TypeScript client for interacting with AWS Bedrock and MCP (Model Context Protocol) servers.

## Features

- Seamless integration with AWS Bedrock's Converse API
- Support for Claude and other Bedrock models
- Connect to MCP servers to discover and use available tools
- Register custom tool handlers
- Event-based architecture for streaming responses
- TypeScript support with full type definitions
- Command-line interface for interactive usage
- Modular design for easy integration into other projects

## Installation

```bash
npm install @juspay/bedrock-mcp-connector
```

## Usage

### Basic Usage

```typescript
import { BedrockMCPClient, LogLevel } from "@juspay/bedrock-mcp-connector";

// Create a client
const client = new BedrockMCPClient({
  modelId: "anthropic.claude-3-sonnet-20240229-v1:0",
  region: "us-east-1",
  systemPrompt: "You are a helpful assistant.",
  mcpServerUrl: "http://localhost:5713/sse", // Optional
});

// Set the log level (optional)
// LogLevel.INFO - Default, shows important information
// LogLevel.DEBUG - Shows detailed debugging information
// LogLevel.WARN - Shows only warnings and errors
// LogLevel.ERROR - Shows only errors
// LogLevel.NONE - Suppresses all logs
client.setLogLevel(LogLevel.INFO);

// Connect to MCP server (if URL is provided)
if (client.mcpServerUrl) {
  await client.connect();
}

// Send a prompt
const response = await client.sendPrompt("What is the capital of France?");
console.log("Response:", response);

// Disconnect when done
if (client.isConnectedToMCP()) {
  await client.disconnect();
}
```

### Using Redis for Persistent Storage

The package supports both in-memory and Redis storage for conversation history:

```typescript
import { BedrockMCPClient } from "@juspay/bedrock-mcp-connector";

// Using Redis storage for persistent conversations
const client = new BedrockMCPClient({
  modelId: "anthropic.claude-3-sonnet-20240229-v1:0",
  region: "us-east-1",
  sessionId: "user-session-123", // Unique session identifier
  userId: "user-456", // Optional user identifier
  storage: {
    type: "redis",
    config: {
      host: "localhost",
      port: 6379,
      password: "your-redis-password", // Optional
      db: 0, // Redis database number
      keyPrefix: "bedrock-mcp:", // Key prefix for Redis keys
      ttl: 86400, // TTL in seconds (24 hours)
      connectionOptions: {
        connectTimeout: 5000,
        lazyConnect: true
      }
    }
  }
});

// Conversations are now persistent across client restarts
const response = await client.sendPrompt("Remember this: my favorite color is blue");
console.log("Response:", response);

// Later, in a new client instance with the same sessionId...
const newClient = new BedrockMCPClient({
  modelId: "anthropic.claude-3-sonnet-20240229-v1:0",
  region: "us-east-1",
  sessionId: "user-session-123", // Same session ID
  storage: { type: "redis", config: { /* same config */ } }
});

const response2 = await newClient.sendPrompt("What's my favorite color?");
// The model will remember the previous conversation!
```

