                    const condition = conditions[Math.floor(Math.random() * conditions.length)];

                    weatherData.forecast.push({
                        date: date.toLocaleDateString(),
                        condition,
                        tempHigh,
                        tempLow
                    });
                }

                logger.debug(`Tool result for ${name}:`, weatherData);

