/**
 * Configuration options for the Bedrock MCP Client
 */
export interface BedrockMCPClientConfig {
    /** The AWS Bedrock model ID to use */
    modelId: string;
    /** The AWS region to use (default: 'us-east-1') */
    region?: string;
    /** The system prompt to use for the model */
    systemPrompt?: string;
    /** The MCP server URL to connect to */
    mcpServerUrl?: string;
    /** The name of the client application */
    clientName?: string;
    /** The version of the client application */
    clientVersion?: string;
    /** Maximum tokens to generate in responses */
    maxTokens?: number;
    /** Temperature for model generation (0.0 to 1.0) */
    temperature?: number;
    /** Optional response output tags to extract specific content */
    responseOutputTags?: [string, string];
    /** Storage configuration for conversation history (default: in-memory) */
    storage?: StorageConfig;
    /** Session identifier for conversation storage */
    sessionId?: string;
    /** User identifier for multi-user scenarios */
    userId?: string;
}

/**
 * Message content item for text
 */
export interface TextContent {
    text: string;
}

/**
 * Message content item for tool use
 */
export interface ToolUseContent {
    toolUse: {
        toolUseId: string;
        name: string;
        input?: Record<string, any>;
    };
}

/**
 * Message content item for tool result
 */
export interface ToolResultContent {
    toolResult: {
        toolUseId: string;
        content: Array<{ text: string }>;
        status: 'success' | 'error';
    };
}

/**
 * Union type for all message content types
 */
export type MessageContent = TextContent | ToolUseContent | ToolResultContent;

/**
 * Message structure for conversation
 */
export interface Message {
    role: 'user' | 'assistant' | 'system';
    content: MessageContent[];
}

/**
 * Tool specification for Bedrock
 */
export interface ToolSpec {
    name: string;
    description?: string;
    inputSchema?: {
        json: Record<string, any>;
    };
}

/**
 * Tool configuration for Bedrock
 */
export interface ToolConfig {
    tools: Array<{
        toolSpec: ToolSpec;
    }>;
}

/**
 * Tool request structure
 */
export interface ToolRequest {
    toolUseId: string;
    name: string;
    input?: Record<string, any>;
}

/**
 * Tool response structure
 */
export interface ToolResponse {
    toolUseId: string;
    content: Array<{ text: string }>;
    status: 'success' | 'error';
}

/**
 * Tool handler function type
 */
export type ToolHandler = (name: string, input: Record<string, any>) => Promise<any>;

/**
 * Events emitted by the BedrockMCPClient
 */
export interface BedrockMCPClientEvents {
    'message': (message: string) => void;
    'error': (error: Error) => void;
    'tool:start': (toolName: string, input: Record<string, any>) => void;
    'tool:end': (toolName: string, result: any) => void;
    'response:start': () => void;
    'response:chunk': (chunk: string) => void;
    'response:end': (fullResponse: string) => void;
    'connected': () => void;
    'disconnected': () => void;
}

/**
 * Typed EventEmitter for BedrockMCPClient
 */
export type BedrockMCPClientEmitter = EventEmitter & {
    on<E extends keyof BedrockMCPClientEvents>(
        event: E,
        listener: BedrockMCPClientEvents[E]
    ): BedrockMCPClientEmitter;

    emit<E extends keyof BedrockMCPClientEvents>(
        event: E,
        ...args: Parameters<BedrockMCPClientEvents[E]>
    ): boolean;
};

/**
 * Log levels
 */
export enum LogLevel {
    DEBUG = 0,
    INFO = 1,
    WARN = 2,
    ERROR = 3,
    NONE = 4
}

/**
 * Logger configuration
 */
export interface LoggerConfig {
    level: LogLevel;
    prefix?: string;
    enableTimestamps?: boolean;
}

/**
 * Simple logger utility
 */
export class Logger {
    private level: LogLevel;
    private prefix: string;
    private enableTimestamps: boolean;

    /**
     * Create a new logger
     * 
     * @param config - Logger configuration
     */
    constructor(config: LoggerConfig) {
        this.level = config.level;
        this.prefix = config.prefix || '';
        this.enableTimestamps = config.enableTimestamps || false;
    }

    /**
     * Log a debug message
     * 
     * @param message - The message to log
     * @param args - Additional arguments to log
     */
    debug(message: string, ...args: any[]): void {
        this.log(LogLevel.DEBUG, message, ...args);
    }

    /**
     * Log an info message
     * 
     * @param message - The message to log
     * @param args - Additional arguments to log
     */
    info(message: string, ...args: any[]): void {
        this.log(LogLevel.INFO, message, ...args);
    }

    /**
     * Log a warning message
     * 
     * @param message - The message to log
     * @param args - Additional arguments to log
     */
    warn(message: string, ...args: any[]): void {
        this.log(LogLevel.WARN, message, ...args);
    }

    /**
     * Log an error message
     * 
     * @param message - The message to log
     * @param args - Additional arguments to log
     */
    error(message: string, ...args: any[]): void {
        this.log(LogLevel.ERROR, message, ...args);
    }

    /**
     * Set the log level
     * 
     * @param level - The log level
     */
    setLevel(level: LogLevel): void {
        this.level = level;
    }

    /**
     * Log a message at the specified level
     * 
     * @param level - The log level
     * @param message - The message to log
     * @param args - Additional arguments to log
     * @private
     */
    private log(level: LogLevel, message: string, ...args: any[]): void {
        if (level < this.level) {
            return;
        }

        let prefix = this.prefix ? `[${this.prefix}] ` : '';

        if (this.enableTimestamps) {
            const timestamp = new Date().toISOString();
            prefix = `[${timestamp}] ${prefix}`;
        }

        const levelPrefix = this.getLevelPrefix(level);
        const formattedMessage = `${prefix}${levelPrefix}${message}`;

        switch (level) {
            case LogLevel.DEBUG:
                console.debug(formattedMessage, ...args);
                break;
            case LogLevel.INFO:
                console.info(formattedMessage, ...args);
                break;
            case LogLevel.WARN:
                console.warn(formattedMessage, ...args);
                break;
            case LogLevel.ERROR:
                console.error(formattedMessage, ...args);
                break;
        }
    }

    /**
     * Get the prefix for the specified log level
     * 
     * @param level - The log level
     * @returns The level prefix
     * @private
     */
    private getLevelPrefix(level: LogLevel): string {
        switch (level) {
            case LogLevel.DEBUG:
                return '[DEBUG] ';
            case LogLevel.INFO:
                return '[INFO] ';
            case LogLevel.WARN:
                return '[WARN] ';
            case LogLevel.ERROR:
                return '[ERROR] ';
            default:
                return '';
        }
    }
}

/**
 * Create a default logger
 * 
 * @param prefix - Optional prefix for log messages
 * @returns A new logger with default configuration
 */
export function createDefaultLogger(prefix?: string): Logger {
    return new Logger({
        level: LogLevel.INFO,
        prefix,
        enableTimestamps: true
    });
}

import { BedrockMCPClient, LogLevel, createDefaultLogger } from '../index.js';

// Create a logger
const logger = createDefaultLogger('Example');
logger.setLevel(LogLevel.DEBUG);

// Configuration
const config = {
    modelId: 'anthropic.claude-3-sonnet-20240229-v1:0',
    region: 'us-east-1',
    systemPrompt: 'You are a helpful assistant that provides concise and accurate information.',
    mcpServerUrl: 'http://localhost:5713/sse', // Optional: MCP server URL
    clientName: 'Example Client',
    clientVersion: '1.0.0',
};

/**
 * Run the example
 */
async function runExample() {
    logger.info('Starting example...');

    // Create the client
    const client = new BedrockMCPClient(config);

    // Set up event listeners
    const emitter = client.getEmitter();

    emitter.on('message', (message) => {
        logger.info(`Message: ${message}`);
    });

    emitter.on('error', (error) => {
        logger.error(`Error: ${error.message}`);
    });

    emitter.on('tool:start', (toolName, input) => {
        logger.info(`Tool started: ${toolName} with input: ${JSON.stringify(input)}`);
    });

    emitter.on('tool:end', (toolName, result) => {
        logger.info(`Tool completed: ${toolName}`);
    });

    emitter.on('response:start', () => {
        logger.info('Response started');
    });

    emitter.on('response:chunk', (chunk) => {
        logger.debug(`Response chunk: ${chunk.substring(0, 50)}...`);
    });

    emitter.on('response:end', (fullResponse) => {
        logger.info('Response completed');
    });

    try {
        // Connect to MCP server if URL is provided
        if (config.mcpServerUrl) {
            try {
                await client.connect();
                logger.info(`Connected to MCP server at ${config.mcpServerUrl}`);

                const tools = client.getTools();
                if (tools.length > 0) {
                    logger.info(`Available tools: ${tools.map(t => t.name).join(', ')}`);
                } else {
                    logger.info('No tools available');
                }
            } catch (error) {
                logger.warn(`Failed to connect to MCP server: ${error instanceof Error ? error.message : String(error)}`);
                logger.info('Continuing without MCP tools');
            }
        }

        // Register a custom tool
        client.registerTool(
            'getCurrentTime',
            async (name, input) => {
                const timezone = input.timezone || 'UTC';
                const date = new Date().toLocaleString('en-US', { timeZone: timezone });
                return { content: [{ text: `The current time is ${date} in ${timezone}` }] };
            },
            'Get the current time in the specified timezone',
            {
                type: 'object',
                properties: {
                    timezone: {
                        type: 'string',
                        description: 'The timezone to get the time for (e.g., UTC, America/New_York)',
                    },
                },
                required: [],
            }
        );

        // Send a prompt
        logger.info('Sending prompt...');
        const response = await client.sendPrompt('What is the capital of France? Also, what time is it now?');

        logger.info('Response:');
        console.log('\n' + response + '\n');

        // Clean up
        if (client.isConnectedToMCP()) {
            await client.disconnect();
            logger.info('Disconnected from MCP server');
        }
    } catch (error) {
        logger.error(`Error: ${error instanceof Error ? error.message : String(error)}`);
    }
}

// Run the example
runExample().catch(error => {
    console.error(`Fatal error: ${error instanceof Error ? error.message : String(error)}`);
    process.exit(1);
});

#!/usr/bin/env node
import readline from 'readline';
import { BedrockMCPClient } from '../client/BedrockMCPClient.js';
import { LogLevel, createDefaultLogger } from '../utils/logging.js';

const logger = createDefaultLogger('CLI');

/**
 * CLI configuration options
 */
interface CLIOptions {
    modelId: string;
    region?: string;
    systemPrompt?: string;
    mcpServerUrl?: string;
    clientName?: string;
    clientVersion?: string;
}

/**
 * Parse command line arguments
 * 
 * @returns The parsed CLI options
 */
function parseArgs(): CLIOptions {
    const args = process.argv.slice(2);
    const options: CLIOptions = {
        modelId: 'anthropic.claude-3-sonnet-20240229-v1:0',
    };

    for (let i = 0; i < args.length; i++) {
        const arg = args[i];

        switch (arg) {
            case '--model':
            case '-m':
                options.modelId = args[++i];
                break;
            case '--region':
            case '-r':
                options.region = args[++i];
                break;
            case '--system-prompt':
            case '-s':
                options.systemPrompt = args[++i];
                break;
            case '--mcp-url':
            case '-u':
                options.mcpServerUrl = args[++i];
                break;
            case '--name':
            case '-n':
                options.clientName = args[++i];
                break;
            case '--version':
            case '-v':
                options.clientVersion = args[++i];
                break;
            case '--help':
            case '-h':
                printHelp();
                process.exit(0);
                break;
        }
    }

    return options;
}

/**
 * Print help message
 */
function printHelp(): void {
    console.log(`
